def all_matchings(C, cap=100000):
 n=len(C); order=sorted(range(n),key=lambda i:C[i].sum()); ans=[]; assign=[-1]*n; used=set()
 def rec(k):
  if len(ans)>=cap:return
  if k==n: ans.append(tuple(assign)); return
  i=order[k]
  for j in np.flatnonzero(C[i]):
   j=int(j)
   if j not in used:
    assign[i]=j; used.add(j); rec(k+1); used.remove(j)
